within Buildings.Controls.OBC.CDL.Reals;
block LimitSlewRate "Limit the increase or decrease rate of input"
  parameter Real raisingSlewRate(
    min=Constants.small,
    unit="1/s")
    "Speed with which to increase the output";
  parameter Real fallingSlewRate(
    max=-Constants.small,
    unit="1/s")=-raisingSlewRate
    "Speed with which to decrease the output";
  parameter Real Td(
    final quantity="Time",
    final unit="s",
    min=Constants.eps)=raisingSlewRate*10
    "Derivative time constant";
  parameter Boolean enable=true
    "Set to false to disable rate limiter";
  Buildings.Controls.OBC.CDL.Interfaces.RealInput u
    "Input signal to be rate of change limited"
    annotation (Placement(transformation(extent={{-140,-20},{-100,20}})));
  Buildings.Controls.OBC.CDL.Interfaces.RealOutput y
    "Rate of change limited output signal"
    annotation (Placement(transformation(extent={{100,-20},{140,20}})));

protected
  Real thr=(u-y)/Td
    "Approximation to derivative between input and output";

initial equation
  assert(raisingSlewRate > 0,
    "raisingSlewRate must be larger than zero.");
  assert(fallingSlewRate < 0,
    "fallingSlewRate must be less than zero.");

  y=u;

model SecondaryController
  parameter SI.PerUnit droop = 0.05 "Droop";
  parameter SI.Power Pnom "Overall system nominal active power";
  parameter SI.Time Ts "Settling time of frequency";
  parameter ThermoPower.Choices.Init.Options initOpt=system.initOpt
    "Initialization option" annotation (Dialog(tab="Initialization"));
  parameter SI.Power powerOffset_start = 0 "Start value of power offset" annotation (Dialog(tab="Initialization"));
  final parameter SI.Frequency f0 = system.fnom "Nominal frequency";
  final parameter SI.AngularFrequency mu = 5*Ts*Pnom/(f0*droop) "Integral controller gain";
  outer System system;

  Modelica.Blocks.Interfaces.RealInput frequency "Measured frequency in Hz" annotation (Placement(
        transformation(extent={{-120,-20},{-80,20}}, rotation=0),
        iconTransformation(extent={{-120,-20},{-80,20}})));
  Modelica.Blocks.Interfaces.RealOutput powerOffset(start = powerOffset_start)
     "Power offset to the plant controllers" annotation (Placement(
        transformation(extent={{100,0},{120,20}},   rotation=0),
        iconTransformation(extent={{80,-20},{120,20}})));

equation
  der(powerOffset) = 5*Pnom/(Ts*droop)*(frequency-f0)/f0;
initial equation
  if initOpt == ThermoPower.Choices.Init.Options.noInit then
    // do nothing

within IBPSA.Controls.OBC.CDL.Reals;
block LimitSlewRate "Limit the increase or decrease rate of input"
  parameter Real raisingSlewRate(
    min=Constants.small,
    unit="1/s")
    "Speed with which to increase the output";
  parameter Real fallingSlewRate(
    max=-Constants.small,
    unit="1/s")=-raisingSlewRate
    "Speed with which to decrease the output";
  parameter Real Td(
    final quantity="Time",
    final unit="s",
    min=Constants.eps)=raisingSlewRate*10
    "Derivative time constant";
  parameter Boolean enable=true
    "Set to false to disable rate limiter";
  IBPSA.Controls.OBC.CDL.Interfaces.RealInput u
    "Input signal to be rate of change limited"
    annotation (Placement(transformation(extent={{-140,-20},{-100,20}})));
  IBPSA.Controls.OBC.CDL.Interfaces.RealOutput y
    "Rate of change limited output signal"
    annotation (Placement(transformation(extent={{100,-20},{140,20}})));
